model.stylesheet:
.bx-chem .model-still *, .bx-chem .model-still *::before, .bx-chem .model-still *::after{ box-sizing: border-box; }
.bx-chem .model-still{ margin: 0; background: var(--raised); color: var(--ink-1); }
.bx-chem .model-still .kx{ --kx-ui: system-ui, "Segoe UI", Roboto, "Noto Sans", Arial, sans-serif; --kx-serif: Georgia, "Noto Serif", "Times New Roman", serif; padding: 16px 16px 18px; font-family: var(--kx-ui); background: var(--raised); color: var(--ink-1); }
.bx-chem .model-still .mb{ display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; padding-bottom: 12px; border-bottom: 1px solid var(--rule); }
.bx-chem .model-still .mb-k{ display: inline-flex; align-items: center; gap: 8px; font: 600 12px/1.3 var(--kx-ui); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-1); }
.bx-chem .model-still .mb-k::before{ content: ""; width: 10px; height: 10px; border: 1.5px dashed var(--ink-2); border-radius: 2px; }
.bx-chem .model-still .mb-d{ font: 400 13px/1.45 var(--kx-ui); color: var(--ink-3); }
.bx-chem .model-still .kx-h{ margin: 14px 0 0; font: 400 clamp(20px, 2vw + 12px, 26px)/1.2 var(--kx-serif); }
.bx-chem .model-still .kx-l{ margin: 6px 0 0; max-width: 66ch; font: 400 16px/1.5 var(--kx-serif); color: var(--ink-2); }
.bx-chem .model-still .kx-st{ position: relative; margin-top: 14px; border: 1px solid var(--ink-1); border-radius: 2px; overflow: hidden; background: var(--sunk); }
.bx-chem .model-still .kx-st svg{ display: block; width: 100%; height: auto; }
.bx-chem .model-still .kx-ph{ position: absolute; left: 12px; top: 10px; margin: 0; padding: 4px 9px 5px; background: var(--raised); border: 1px solid var(--rule); border-radius: 4px; font: 600 13px/1.3 var(--kx-ui); color: var(--ink-1); }
.bx-chem .model-still .kx-c{ margin-top: 14px; display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 10px 16px; align-items: center; }
.bx-chem .model-still .kx-b{ display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px; padding: 0 18px; border-radius: 4px; border: 1px solid var(--rule-strong); background: transparent; color: var(--ink-1); font: 500 14px/1 var(--kx-ui); cursor: pointer; }
.bx-chem .model-still .kx-b:hover{ border-color: var(--ink-1); background: var(--sunk); }
.bx-chem .model-still .kx-b:focus-visible, .bx-chem .model-still .kx-s input:focus-visible{ outline: 2px solid var(--indigo); outline-offset: 3px; }
.bx-chem .model-still .kx-b svg{ width: 13px; height: 13px; }
.bx-chem .model-still .kx-s{ display: grid; gap: 4px; min-width: 0; }
.bx-chem .model-still .kx-s input{ width: 100%; margin: 0; height: 28px; accent-color: var(--indigo); }
.bx-chem .model-still .kx-tk{ display: grid; grid-template-columns: 23fr 23fr 16fr 38fr; font: 400 12px/1.2 var(--kx-ui); color: var(--ink-3); }
.bx-chem .model-still .kx-tk span{ border-left: 1px solid var(--rule); padding-left: 6px; white-space: nowrap; overflow: hidden; }
.bx-chem .model-still .kx-n{ margin: 12px 0 0; display: flex; flex-wrap: wrap; gap: 4px 20px; font: 400 13px/1.45 var(--kx-ui); color: var(--ink-2); font-variant-numeric: lining-nums tabular-nums; }
.bx-chem .model-still .kx-n b{ font-weight: 600; color: var(--ink-1); }
.bx-chem .model-still .kx-k{ margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--rule); display: flex; flex-wrap: wrap; gap: 8px 18px; font: 400 12px/1.3 var(--kx-ui); color: var(--ink-2); }
.bx-chem .model-still .kx-k span{ display: inline-flex; align-items: center; gap: 7px; }
.bx-chem .model-still .kx-k svg{ width: 22px; height: 14px; }
.bx-chem .model-still .vh{ position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.bx-chem .model-still .t{ font: 400 13px/1 var(--kx-ui); font-size: calc(13px * var(--k, 1)); fill: var(--ink-2); }
.bx-chem .model-still .t1{ font: 600 12px/1 var(--kx-ui); font-size: calc(12px * var(--k, 1)); letter-spacing: 0.08em; fill: var(--ink-1); }
.bx-chem .model-still .kx-st svg *{ vector-effect: non-scaling-stroke; }
.bx-chem .model-still .ln{ stroke: var(--ink-3); stroke-width: 1; fill: none; }
.bx-chem .model-still .liq{ fill: var(--dye-vat-liquor); fill-opacity: 0.5; }
.bx-chem .model-still .liq-l{ stroke: var(--ink-2); stroke-opacity: 0.6; fill: none; }
.bx-chem .model-still .fw{ fill: var(--dye-cloth); }
.bx-chem .model-still .fo{ fill: none; stroke: var(--ink-1); stroke-width: 1.3; stroke-linejoin: round; }
.bx-chem .model-still .fr{ fill: none; stroke: var(--ink-1); stroke-opacity: 0.18; }
.bx-chem .model-still .tw{ fill: none; stroke: var(--ink-1); stroke-opacity: 0.35; stroke-width: 1; }
.bx-chem .model-still .tg{ fill: var(--dye-leuco); }
.bx-chem .model-still .tb{ fill: var(--dye-indigo); }
.bx-chem .model-still .lu{ fill: var(--sunk); stroke: var(--ink-1); stroke-width: 1.2; }
.bx-chem .model-still .pl{ fill: var(--raised); stroke: var(--ink-1); stroke-width: 1.6; }
.bx-chem .model-still .pi{ fill: var(--dip-1); stroke: var(--ink-1); stroke-width: 1.4; }
.bx-chem .model-still .ox circle{ fill: var(--raised); stroke: var(--ink-1); stroke-width: 1.4; }
.bx-chem .model-still .wa{ fill: var(--raised); stroke: var(--ink-2); stroke-width: 1; }
.bx-chem .model-still .mc{ fill: var(--dye-cloth); stroke: var(--ink-2); stroke-width: 1; }
@media (max-width: 560px){.bx-chem .model-still .kx-c{ grid-template-columns: minmax(0, 1fr); }
.bx-chem .model-still .kx-b{ width: 100%; }}
